class Service:
    def __init__(self, name, namespace):
        self.name = name
        self.namespace = namespace
        self.endpoints = []
        self._next = 0

    @property
    def dns_name(self):
        return f"{self.name}.{self.namespace}.svc.cluster.local"

    def sync_endpoints(self, pods, selector):
        self.endpoints = [p["ip"] for p in pods if selector.items() <= p["labels"].items()]

    def route(self):
        if not self.endpoints:
            return None
        ip = self.endpoints[self._next % len(self.endpoints)]
        self._next += 1
        return ip


pods = [
    {"ip": "10.0.0.11", "labels": {"app": "api"}},
    {"ip": "10.0.0.12", "labels": {"app": "api"}},
    {"ip": "10.0.0.13", "labels": {"app": "worker"}},
]

svc = Service("api", "shop")
svc.sync_endpoints(pods, {"app": "api"})
print(svc.dns_name)
print("endpoints:", svc.endpoints)
for _ in range(4):
    print("request ->", svc.route())
